const crypto = require('crypto');
const tenantId = $env.TENANT_ID;
const secret = $env.TENANT_WEBHOOK_SECRET;
if (!tenantId || !secret) throw new Error('TENANT_ID / TENANT_WEBHOOK_SECRET are not configured in n8n');
const body = JSON.stringify({ correlationId: 'followup-' + new Date().toISOString().slice(0, 13), limit: 10 });
const ts = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
return [{ json: { url: $env.API_BASE_URL + '/automation/followups/draft-due', body, headers: { 'content-type': 'application/json', 'x-tenant-id': tenantId, 'x-automation-timestamp': ts, 'x-automation-signature': signature } } }];
